<?php
declare(strict_types=1);
require __DIR__ . '/../../../../lib/app.php';
require_once __DIR__ . '/../../home/php/neuria_cliente.php';
app_require_mode([0,1,2]);
$db=app_db();$q=trim((string)($_POST['q']??''));$state=trim((string)($_POST['estado']??''));$deleted=($_POST['eliminadas']??'0')==='1';
$where=[$deleted?'n.deleted_at IS NOT NULL':'n.deleted_at IS NULL'];$types='';$params=[];
if($q!==''){$where[]='(n.titulo LIKE ? OR n.bajada LIKE ? OR n.volanta LIKE ?)';$term='%'.$q.'%';$types.='sss';array_push($params,$term,$term,$term);}
if(in_array($state,['pendiente','activa','suspendida'],true)){$where[]='n.estado=?';$types.='s';$params[]=$state;}
$news=$state==='oferta'?[]:$db->all('SELECT n.*,(SELECT COUNT(*) FROM noticia_archivos a WHERE a.noticia_id=n.id AND a.deleted_at IS NULL) archivos FROM noticias n WHERE '.implode(' AND ',$where).' ORDER BY COALESCE(n.publicacion_at,n.created_at) DESC,n.id DESC',$types,$params);
$offerResult=['ok'=>true,'items'=>[]];
if(!$deleted&&($state===''||$state==='oferta'))$offerResult=(new NeuriaCliente())->listar(100);
$imported=array_flip(array_map('intval',array_column($db->all('SELECT neuria_id FROM noticias WHERE neuria_id IS NOT NULL'),'neuria_id')));
$offers=[];if($offerResult['ok'])foreach($offerResult['items'] as $item){if(isset($imported[(int)$item['id']]))continue;if($q!==''&&stripos($item['titulo'].' '.$item['bajada'],$q)===false)continue;$offers[]=$item;}
$stateLabels=['pendiente'=>'Pendiente','activa'=>'Activa','suspendida'=>'Suspendida'];
?>
<section class="admin-page"><div class="container-fluid px-3 px-lg-4">
<div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><h1 class="h3 mb-1">Noticias</h1><p class="text-secondary mb-0">Producción editorial propia y contenidos ofrecidos por Neuria.</p></div><button class="btn btn-primary" onclick="cargar_post('modulos/noticias/php/app_form.php','news-panel','')"><i class="bi bi-plus-lg me-2"></i>Nueva noticia</button></div>
<?php if(!$offerResult['ok']):?><div class="alert alert-warning"><i class="bi bi-cloud-slash me-2"></i>Neuria no está disponible temporalmente. Las noticias locales continúan operativas.</div><?php endif;?>
<form id="news-filter" class="card admin-card mb-4"><div class="card-body"><div class="row g-2 align-items-end"><div class="col-lg-6"><label class="form-label">Buscar</label><input class="form-control" name="q" value="<?=app_escape($q)?>" placeholder="Título, bajada o volanta"></div><div class="col-md-4 col-lg-3"><label class="form-label">Estado</label><select class="form-select" name="estado"><option value="">Todos</option><option value="oferta" <?=$state==='oferta'?'selected':''?>>Oferta de Neuria</option><?php foreach($stateLabels as $value=>$label):?><option value="<?=$value?>" <?=$state===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-4 col-lg-2"><label class="form-label">Registros</label><select class="form-select" name="eliminadas"><option value="0" <?=$deleted?'':'selected'?>>Activos</option><option value="1" <?=$deleted?'selected':''?>>Eliminados</option></select></div><div class="col-md-4 col-lg-1"><button class="btn btn-outline-primary w-100"><i class="bi bi-search"></i></button></div></div></div></form>
<div id="news-panel"></div><div class="card admin-card"><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover align-middle admin-table mb-0"><thead><tr><th>Noticia</th><th>Origen</th><th>Sección</th><th>Publicación</th><th>Estado</th><th class="text-end">Acciones</th></tr></thead><tbody>
<?php if(!$news&&!$offers):?><tr><td colspan="6" class="text-center text-secondary py-5">No se encontraron noticias.</td></tr><?php endif;?>
<?php foreach($offers as $item):?><tr class="table-warning"><td data-label="Noticia"><strong><?=app_escape($item['titulo'])?></strong><small class="d-block text-secondary text-truncate" style="max-width:38rem"><?=app_escape($item['bajada'])?></small></td><td data-label="Origen">Neuria</td><td data-label="Sección"><?=app_escape($item['tipo']?:'Sin definir')?></td><td data-label="Publicación"><?=app_escape($item['aprobado']?:$item['actualizado'])?></td><td data-label="Estado"><span class="badge text-bg-warning">Oferta</span></td><td data-label="Acciones" class="text-end"><button class="btn btn-sm btn-outline-primary" onclick="cargar_post('modulos/noticias/php/app_form.php','news-panel',{neuria_id:<?=(int)$item['id']?>})"><i class="bi bi-search me-1"></i>Revisar</button></td></tr><?php endforeach;?>
<?php foreach($news as $item):$isDeleted=$item['deleted_at']!==null;?><tr><td data-label="Noticia"><strong><?=app_escape($item['titulo'])?></strong><small class="d-block text-secondary text-truncate" style="max-width:38rem"><?=app_escape($item['bajada'])?></small></td><td data-label="Origen"><?=app_escape(ucfirst($item['origen']))?><?php if($item['archivos']):?><small class="d-block text-secondary"><?=$item['archivos']?> archivo/s</small><?php endif;?></td><td data-label="Sección"><?=app_escape($item['seccion']?:'Sin definir')?></td><td data-label="Publicación"><?=app_escape($item['publicacion_at']?:'Sin programar')?></td><td data-label="Estado"><span class="badge <?=$item['estado']==='activa'?'text-bg-success':($item['estado']==='suspendida'?'text-bg-danger':'text-bg-secondary')?>"><?=app_escape($stateLabels[$item['estado']]??$item['estado'])?></span></td><td data-label="Acciones" class="text-end"><div class="btn-group btn-group-sm"><?php if(!$isDeleted):?><button class="btn btn-outline-primary" title="Editar" onclick="cargar_post('modulos/noticias/php/app_form.php','news-panel',{id:<?=(int)$item['id']?>})"><i class="bi bi-pencil"></i></button><button class="btn btn-outline-secondary" title="Cambiar estado" onclick="newsAction('cycle',<?=(int)$item['id']?>)"><i class="bi bi-arrow-repeat"></i></button><button class="btn btn-outline-danger" title="Eliminar" onclick="newsAction('archive',<?=(int)$item['id']?>)"><i class="bi bi-trash"></i></button><?php else:?><button class="btn btn-outline-success" title="Restaurar" onclick="newsAction('restore',<?=(int)$item['id']?>)"><i class="bi bi-arrow-counterclockwise"></i></button><?php endif;?></div></td></tr><?php endforeach;?>
</tbody></table></div></div></div></div></section>
<script>function newsReload(){cargar_post('modulos/noticias/php/app_home.php','content_seccion',$('#news-filter').serialize())}function newsAction(action,id){if(confirm(action==='archive'?'¿Eliminar esta noticia?':'¿Confirmar el cambio?'))appAction('modulos/noticias/php/app_action.php',{action:action,id:id},newsReload)}$('#news-filter').on('submit',function(e){e.preventDefault();newsReload()});</script>
